INSERT INTO `users` (`id`, `name`, `email`, `password_hash`, `phone`, `role`, `wilaya`, `municipality`, `avatar`, `bio`) VALUES
(1, 'مديرية الشباب والرياضة - بشار', 'admin@djs-bechar.dz', @pwd, '049811223', 'admin', '08 - بشار', 'بشار', 'admin.svg', 'الحساب الرسمي لمتابعة وإشراف وتوثيق العمل التطوعي بمؤسسات الشباب لولاية بشار.'),
(2, 'نادي المواطنة والعمل التطوعي', 'club.kenadsa@djs-bechar.dz', @pwd, '0661223344', 'club', '08 - بشار', 'القنادسة', 'club1.svg', 'نادي شبابي يعنى بنشاطات حماية المحيط والعمل التطوعي والمواطنة الفاعلة في بلدية القنادسة.'),
(3, 'نادي الإبداع الرقمي والابتكار', 'club.numerique@djs-bechar.dz', @pwd, '0662334455', 'club', '08 - بشار', 'بشار', 'club2.svg', 'فضاء لتدريب وتمكين الشباب في المهارات الرقمية والبرمجة وحملات محو الأمية الرقمية.'),
(4, 'جمعية حماية واحات الساورة', 'club.taghit@djs-bechar.dz', @pwd, '0663445566', 'club', '08 - بشار', 'تاغيت', 'club3.svg', 'جمعية شبابية ناشطة في المحافظة على التراث البيئي وواحات النخيل والسياحة البيئية المسؤولة.'),
(5, 'أمين بلقاسم', 'amine@volunteer.dz', @pwd, '0771889900', 'volunteer', '08 - بشار', 'بشار', 'vol1.svg', 'طالب جامعي شغوف بالبرمجة والتطوع البيئي والمجتمعي بولاية بشار.'),
(6, 'فاطمة الزهراء قدور', 'fatima@volunteer.dz', @pwd, '0772990011', 'volunteer', '08 - بشار', 'القنادسة', 'vol2.svg', 'ناشطة جمعوية ومصممة جرافيك متطوعة في مبادرات مؤسسات الشباب.'),
(7, 'ياسين بن علي', 'yassine@volunteer.dz', @pwd, '0773001122', 'volunteer', '08 - بشار', 'تاغيت', 'vol3.svg', 'مهتم بالسياحة البيئية وتنظيم الأنشطة الميدانية في منطقة تاغيت.');
INSERT INTO `clubs_profile` (`id`, `user_id`, `organization_name`, `institution_type`, `bio`, `logo`, `wilaya`, `municipality`, `address`, `verified`) VALUES
(1, 2, 'نادي المواطنة دار الشباب القنادسة', 'دار الشباب', 'نادي معتمد تابع لدار الشباب الشهيد عمارة بالقنادسة، ينظم حملات دورية لخدمة المجتمع المحلي والبيئة.', 'club1.svg', '08 - بشار', 'القنادسة', 'شارع الاستقلال، القنادسة، بشار', 1),
(2, 3, 'نادي الإبداع الرقمي مركب الشباب', 'مركب التسلية العلمية', 'حاضنة للأنشطة التكنولوجية وورشات الرقمنة ونشر الثقافة التقنية بين صفوف الشباب.', 'club2.svg', '08 - بشار', 'بشار', 'حي الهدى، قرب المسبح الأولمبي، بشار', 1),
(3, 4, 'جمعية واحات تاغيت البيئية', 'بيت الشباب تاغيت', 'مبادرة شبابية تهدف لحماية التراث الواحاتي وتنظيف المعالم السياحية والأثرية بتاغيت.', 'club3.svg', '08 - بشار', 'تاغيت', 'وسط واحة تاغيت، قبالة الكثبان الرملية', 1);
INSERT INTO `campaigns` (`id`, `club_id`, `title`, `description`, `category`, `wilaya`, `municipality`, `location_name`, `start_date`, `end_date`, `daily_start_time`, `daily_end_time`, `hours_count`, `min_volunteers`, `status`, `image`) VALUES
(1, 1, 'حملة تشجير وتنظيف محيط دار الشباب القنادسة', 'نهدف إلى غرس 100 شجيرة محلية مقاومة للجفاف وتهيئة المساحات الخضراء ومكتبة الهواء الطلق بدار الشباب لخدمة أبناء البلدية.', 'بيئة وتراث', '08 - بشار', 'القنادسة', 'محيط دار الشباب الشهيد عمارة - القنادسة', '2026-09-22', '2026-09-22', '08:00', '13:00', 5, 20, 'published', 'camp1.jpg'),
(2, 2, 'ورشة محو الأمية الرقمية وتدريب كبار السن على الهاتف الذكي', 'فرصة تطوعية للشباب الشغوفين بالتقنية لمساعدة الآباء وكبار السن على استعمال التطبيقات الحكومية الرقمية (بريدي موب، البوابة الوطنية).', 'رقمنة وتدريب', '08 - بشار', 'بشار', 'قاعة الرقمنة - مركب الشباب بشار', '2026-09-25', '2026-09-26', '09:00', '12:00', 6, 12, 'published', 'camp2.jpg'),
(3, 3, 'تنظيف وتأهيل مسار واحة تاغيت التاريخية', 'حملة ميدانية كبرى لجمع المخلفات البلاستيكية وصيانة سواقي الري التقليدية بالواحة استعداداً للموسم السياحي الشتوي.', 'بيئة وتراث', '08 - بشار', 'تاغيت', 'واحة النخيل ومحيط القصر العتيق تاغيت', '2026-10-02', '2026-10-03', '07:30', '11:30', 8, 25, 'published', 'camp3.jpg'),
(4, 2, 'تنظيم وإرشاد زوار الأسبوع الولائي للابتكار والذكاء الاصطناعي', 'المشاركة في استقبال وتوجيه الوفود المشاركة وتنظيم منصات العرض وتأطير ورشات العمل التفاعلية.', 'تنظيم فعاليات', '08 - بشار', 'بشار', 'قاعة المعارض الكبرى - دار الثقافة بشار', '2026-10-10', '2026-10-12', '08:30', '14:30', 12, 15, 'published', 'camp4.jpg'),
(5, 1, 'تهيئة وفرز مكتبة بلدية وتجهيز ركن القراءة للطفل', 'حملة تطوعية لتصنيف وفهرسة الكتب المتبرع بها وإعادة طلاء وتزيين جدران قاعة المطالعة المخصصة للأطفال والشباب.', 'ثقافة ومواطنة', '08 - بشار', 'القنادسة', 'مكتبة المطالعة العمومية - القنادسة', '2026-08-15', '2026-08-16', '08:00', '12:00', 8, 10, 'completed', 'camp5.jpg');
