INSERT INTO `notifications` (`id`, `user_id`, `title`, `message`, `link`, `is_read`, `created_at`) VALUES
(1, 5, 'ساعات تطوع معتمدة!', 'تهانينا! تم اعتماد 8 ساعات تطوع في حملة تهيئة وفرز مكتبة بلدية وإضافتها إلى جواز التطوع الرقمي الخاص بك.', 'passport', 0, '2026-08-16 18:30:00'),
(2, 5, 'فرصة تطوع جديدة', 'نشر نادي المواطنة دار الشباب القنادسة حملة جديدة: حملة تشجير وتنظيف محيط دار الشباب.', 'campaign_detail&id=1', 1, '2026-09-15 10:00:00'),
(3, 6, 'ساعات تطوع معتمدة!', 'تهانينا! تم اعتماد 8 ساعات تطوع في حملة تهيئة وفرز مكتبة بلدية، يمكنك الآن تحميل شهادتك الموثقة.', 'passport', 0, '2026-08-16 18:30:00'),
(4, 2, 'طلب انضمام جديد', 'سجل المتطوع أمين بلقاسم في حملة تشجير وتنظيف محيط دار الشباب القنادسة.', 'club_attendees&id=1', 1, '2026-09-15 14:20:00');
